std::mutex resource_mutex;
static int shared_buffer[10];

void access_resource(int index) {
    // std::mutex::lock() waits (potentially blocks the thread)
    // until the underlying atomic state transition is successful,
    // guaranteeing exclusive ownership.
    resource_mutex.lock();

    shared_buffer[index] = index * 2; // Critical Section

    resource_mutex.unlock();
}

// Idiomatic (safer) alternative using RAII:
void access_via_guard(int index) {
    std::lock_guard<std::mutex> guard(resource_mutex);
    shared_buffer[index] = index + 1;
}
